    ('1af1e7a9-efc1-52b8-adaa-c01f4b863ba9'::uuid, 'philosophie', 'Tle', 'Le bonheur', 4),
    ('15c7919c-6b47-5ac7-b80f-aae35ae12c84'::uuid, 'philosophie', 'Tle', 'Le travail', 5),
    ('a9c5fb62-742f-5f14-8097-2203333654b9'::uuid, 'philosophie', 'Tle', 'L’État', 6),
