    ('f7d54ea5-7a57-5c35-8910-ef6e1fd05c7d'::uuid, 'philosophie', 'Tle', 'Le devoir', 8),
    ('8a83108a-1f1c-5b30-93cc-4e06e42a79e3'::uuid, 'philosophie', 'Tle', 'La raison', 9),
    ('e91004a8-9ad3-5a14-992e-add1a97a8730'::uuid, 'philosophie', 'Tle', 'La liberté de faire ce qui me plaît', 10),
    ('ec09b321-34f9-5e16-88ea-7d5fcebe79ab'::uuid, 'philosophie', 'Tle', 'Le libre arbitre', 11),
    ('00a8ab06-4e88-5e98-ac95-4c986eb57c10'::uuid, 'philosophie', 'Tle', 'La liberté politique', 12),
    ('8db367be-d98a-518c-8116-d39e8f5f129d'::uuid, 'philosophie', 'Tle', 'Le langage', 13),
    ('36834bd6-7806-517b-9ff1-2ce9ee56f042'::uuid, 'philosophie', 'Tle', 'La vérité', 14),
    ('e96db71d-2388-59bd-ab80-9b5d2e71f4be'::uuid, 'philosophie', 'Tle', 'La science', 15),
